source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    by_color = defaultdict(list)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg:
                by_color[value].append((r, c))
    out = [row[:] for row in grid]
    lines = []
    for color, points in by_color.items():
        for slope in (-1, 1):
            groups = defaultdict(list)
            for r, c in points:
                groups[c - slope*r].append((r, c))
            lines.extend((color, slope, line) for line in groups.values() if len(line) >= 2)
    # Continue the shortest repeated diagonal pattern(s); tied patterns are all continued.
    if lines:
        shortest = min(len(line) for _, _, line in lines)
        for color, slope, line in lines:
            if len(line) != shortest:
                continue
            line.sort()
            first_r, first_c = line[0]
            last_r, last_c = line[-1]
            for r in range(first_r, last_r+1):
                c = first_c + slope*(r-first_r)
                if out[r][c] == bg or out[r][c] == color:
                    out[r][c] = color
            for r, c, dr in ((first_r, first_c, -1), (last_r, last_c, 1)):
                while 0 <= r+dr < h:
                    r += dr
                    c += slope*dr
                    if not 0 <= c < w:
                        break
                    if out[r][c] != bg and out[r][c] != color:
                        break
                    out[r][c] = color
    return out
'''
